const orgGlobalRoleURN = `-- name: OrgGlobalRoleURN :one
SELECT ('role:global:' || id)::text AS role_urn
FROM global_roles WHERE workos_slug = $1::text AND deleted_at IS NULL LIMIT 1
`

// Global roles are synced from WorkOS in real envs; tolerate their absence
// locally (no row).
func (q *Queries) OrgGlobalRoleURN(ctx context.Context, workosSlug string) (string, error) {
	row := q.db.QueryRow(ctx, orgGlobalRoleURN, workosSlug)
	var role_urn string
	err := row.Scan(&role_urn)
	return role_urn, err
}

